				const current = stack.pop() as string;
				let entries: string[];
				try {
					entries = await readdir(current);
				} catch {
					continue;
				}
				for (const name of entries) {
					const p = join(current, name);
					try {
						const s = await stat(p);
						if (s.isDirectory()) stack.push(p);
						else if (s.isFile()) total += s.size;
					} catch {
