      if (regionLocale && locale !== regionLocale) setLocale(regionLocale);
    }
    setRegion(region);
  };

  return (
    <InternalRegionSelector
      region={region}
      regions={regions}
      regionData={regionData}
      setRegion={changeRegion}
      {...props}
    />
  );
}

